#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;
using pii = pair<int, int>;

const ll N = 5e5 + 5, M = 25, P = 1e9 + 7;

int n, a[N], b[N];
pii st[M][N];
ll f[N];
vector<int> p[N];

pii query(int l, int r)
{
	int k = __lg(r - l + 1);
	return max(st[k][l], st[k][r - (1 << k) + 1]);
}

void init() {}

namespace brute_force
{
	void solve1()
	{
		f[0] = 1;
		for (int i = 1; i <= n; ++i)
		{
			for (int j = 0; j < i; ++j)
			{
				for (int k = j + 2; k < i - 1; ++k)
				{
					if (a[k] != a[i] || a[k + 1] != a[j + 1] || query(j + 1, k).first > query(k + 1, i).first)
						continue;
					(f[i] += f[j]) >= P ? f[i] -= P : 0;
				}
			}
		}
		cout << f[n] << endl;
	}

	void solve2()
	{
		f[0] = 1;
		for (int i = 1; i <= n; ++i)
		{
			for (int j = 0, k, t; j < i; ++j)
			{
				k = min(i - 2, query(j + 1, i).second - 1), t = a[i] * 1000 + a[j + 1];
				(f[i] += f[j] * (upper_bound(p[t].begin(), p[t].end(), k) - lower_bound(p[t].begin(), p[t].end(), j + 2))) %= P;
			}
		}
		cout << f[n] << endl;
	}
}

void solve()
{
	cin >> n;
	for (int i = 1; i <= n; ++i)
		cin >> a[i];
	for (int i = 1; i <= n; ++i)
		cin >> st[0][i].first, st[0][i].second = i;
	for (int j = 1; j <= __lg(n); ++j)
	{
		for (int i = 1; i + (1 << j) - 1 <= n; ++i)
			st[j][i] = max(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
	}
	if (n <= 200)
		return brute_force::solve1();
	for (int i = 1; i < n; ++i)
		p[a[i] * 1000 + a[i + 1]].push_back(i);
	if (n <= 3000)
		return brute_force::solve2();
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

